import { createStickToBottom, definePrimitive } from "@ui-sdk/core"

type ConversationOptions = {
  /** Whether it follows new messages from the start. `false` opens a thread where the reader left it. */
  initial?: boolean
  /** How close to the end, in pixels, still counts as at the bottom. */
  threshold?: number
  /** Whether there are older messages to load above. */
  hasOlder?: boolean
  /** Loads older messages; add them above in one update, and resolve once they are in state. */
  onLoadOlder?: () => unknown
}

type ConversationMessageItem = { value: string; label: string }

const MESSAGE = '[data-slot="conversation-message"]'
const LOG = '[data-slot="conversation-log"]'

function prefersReducedMotion() {
  return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches
}

function textOf(element: Element | null) {
  return element?.textContent?.replace(/\s+/g, " ").trim() ?? ""
}

/** A message as agents read it: its author, then its text, cut to 200 characters. */
function describeMessage(element: Element, index: number): ConversationMessageItem {
  const author = textOf(element.querySelector('[data-slot="conversation-message-author"]'))
  const content = textOf(element.querySelector('[data-slot="conversation-message-content"]')).slice(0, 200)
  const value = element.getAttribute("data-message-id") ?? String(index)
  return { value, label: author ? `${author}: ${content}` : content }
}

// Counts the messages that arrive after the one that was newest, so older messages loaded above never count.
function countArrivals(log: HTMLElement, onArrive: (count: number) => void) {
  const newestOf = () => {
    const all = log.querySelectorAll(MESSAGE)
    return { all, newest: all.item(all.length - 1) as Element | null }
  }
  let last = newestOf().newest
  const observer = new MutationObserver(() => {
    const { all, newest } = newestOf()
    if (newest === last) return
    const index = last?.isConnected ? [...all].indexOf(last) : -1
    const arrived = last === null ? all.length : index === -1 ? 0 : all.length - 1 - index
    last = newest
    if (arrived > 0) onArrive(arrived)
  })
  observer.observe(log, { childList: true, subtree: true })
  return () => observer.disconnect()
}

const conversation = definePrimitive({
  name: "conversation",
  options: { initial: "boolean", threshold: "number", hasOlder: "boolean", onLoadOlder: "action" },
  state: (options: ConversationOptions) => ({
    following: options.initial ?? true,
    atBottom: options.initial ?? true,
    unseen: false,
    newBelow: 0,
    hasOlder: Boolean(options.hasOlder),
    loadingOlder: false,
  }),
  sync: (options) => ({ hasOlder: Boolean(options.hasOlder) }),
  api: (context) => {
    const { store } = context
    const stick = createStickToBottom({
      initial: context.options().initial ?? true,
      threshold: context.options().threshold ?? 48,
    })
    context.onDestroy(
      stick.subscribe(() => {
        const next = stick.get()
        store.set({ ...next, newBelow: next.following ? 0 : store.get().newBelow })
      }),
    )
    return {
      /** Follows the log's end and counts arrivals while the reader is scrolled up. */
      connect(log: HTMLElement) {
        const disconnect = stick.connect(log)
        const stopCounting = countArrivals(log, (count) => {
          if (!stick.get().following) store.set({ newBelow: store.get().newBelow + count })
        })
        return () => {
          stopCounting()
          disconnect()
        }
      },
      /** Scrolls to the newest message and follows again; smooth unless the reader prefers reduced motion. */
      jumpToLatest() {
        stick.scrollToBottom({ behavior: prefersReducedMotion() ? "auto" : "smooth" })
        store.set({ newBelow: 0 })
        return true
      },
      /** Stops following, as if the reader scrolled up. */
      release() {
        stick.release()
      },
      /** Keeps the view in place while `onLoadOlder` adds messages above. */
      async loadOlder() {
        const { hasOlder, loadingOlder } = store.get()
        const load = context.options().onLoadOlder
        if (!hasOlder || loadingOlder || !load) return false
        store.set({ loadingOlder: true })
        stick.prepend()
        try {
          await load()
        } finally {
          store.set({ loadingOlder: false })
        }
        return true
      },
      /** The messages on the page, oldest first, as `{ value, label }`. */
      messages(): ConversationMessageItem[] {
        const log = context.element("log")
        return log ? [...log.querySelectorAll(MESSAGE)].map(describeMessage) : []
      },
    }
  },
  slots: (slot) => ({
    root: slot<
      {},
      { following: boolean; atBottom: boolean; newBelow: number; hasOlder: boolean; loadingOlder: boolean }
    >({
      state: (state) => ({
        following: state.following,
        atBottom: state.atBottom,
        newBelow: state.newBelow,
        hasOlder: state.hasOlder,
        loadingOlder: state.loadingOlder,
      }),
      attrs: (state) => ({
        "data-following": state.following ? "" : undefined,
        "data-unseen": state.unseen ? "" : undefined,
      }),
    }),
    log: slot({
      role: "log",
      // The log scrolls, so it takes focus for keyboard scrolling.
      attrs: () => ({ tabindex: "0" }),
      bind: (el, { api }) => api.connect(el),
    }),
    newBelow: slot<{}, { newBelow: number }>({
      role: "button",
      focus: "native",
      present: (state) => !state.following,
      state: (state) => ({ newBelow: state.newBelow }),
      attrs: (state) => ({ type: "button", "data-count": String(state.newBelow) }),
      press: ({ api, el }) => {
        const hadFocus = el !== undefined && el.ownerDocument.activeElement === el
        api.jumpToLatest()
        // The button leaves once following resumes, so focus moves to the log rather than falling to the page.
        if (hadFocus) {
          const log = el.closest('[data-slot="conversation"]')?.querySelector<HTMLElement>(LOG)
          log?.focus({ preventScroll: true })
        }
      },
    }),
    loadOlder: slot<{}, { loadingOlder: boolean }>({
      role: "button",
      focus: "native",
      present: (state) => state.hasOlder,
      state: (state) => ({ loadingOlder: state.loadingOlder }),
      attrs: (state) => ({
        type: "button",
        "aria-busy": state.loadingOlder ? "true" : undefined,
        "data-pending": state.loadingOlder ? "" : undefined,
      }),
      press: ({ api }) => void api.loadOlder(),
    }),
  }),
  agent: { actions: ["jumpToLatest", "loadOlder"], items: (api) => api.messages() },
})

export { conversation, describeMessage }
export type { ConversationMessageItem, ConversationOptions }

"use client"

import { createParts, usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { createContext, use, useId, type ComponentProps, type ReactNode } from "react"
import { ArrowDownIcon } from "lucide-react"

import { buttonVariants } from "@/components/ui/button"
import { conversation, type ConversationOptions } from "@/components/ui/conversation-primitive"
import { RelativeTime } from "@/components/ui/relative-time"
import type { Instant } from "@/lib/time"
import { cn, cnState } from "@/lib/utils"

const Parts = createParts(conversation, { root: "div", log: "div", newBelow: "button", loadOlder: "button" })

type ConversationApi = ReturnType<typeof usePrimitive<typeof conversation>>["api"]

const ConversationContext = createContext<ConversationApi | null>(null)

/** The nearest `Conversation`'s api (`jumpToLatest`, `release`, `loadOlder`), or null outside one. */
function useConversation() {
  return use(ConversationContext)
}

type ConversationRole = "user" | "assistant" | "agent" | "system" | "tool"

type ConversationLabels = {
  /** The pill's text while messages arrived below: "3 new below". */
  newBelow: (count: number) => string
  /** The pill's text while scrolled up with nothing new. */
  jumpToLatest: string
  loadOlder: string
}

const conversationLabels: ConversationLabels = {
  newBelow: (count) => `${String(count)} new below`,
  jumpToLatest: "Jump to latest",
  loadOlder: "Load older messages",
}

type ConversationRootState = {
  following: boolean
  atBottom: boolean
  newBelow: number
  hasOlder: boolean
  loadingOlder: boolean
}

type ConversationRootProps = PartProps<"div", ConversationRootState> & ConversationOptions

/** The primitive's root, which shares its api with `ConversationComposer` and `useConversation`. */
function ConversationRoot({ initial, threshold, hasOlder, onLoadOlder, className, ...props }: ConversationRootProps) {
  const handle = usePrimitive(conversation, { initial, threshold, hasOlder, onLoadOlder })
  const root = usePart(
    handle,
    "root",
    {},
    { ...props, className: cnState("relative flex h-full min-h-0 flex-col", className) },
    "div",
  )
  return <ConversationContext value={handle.api}>{root}</ConversationContext>
}

function ConversationLog({ className, ...props }: ComponentProps<typeof Parts.Log>) {
  return (
    <Parts.Log
      className={cnState(
        "flex min-h-0 flex-1 flex-col gap-group overflow-y-auto overscroll-contain p-inset-surface outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
        className,
      )}
      {...props}
    />
  )
}

function ConversationNewBelow({
  className,
  labels: labelsProp,
  children,
  ...props
}: Omit<ComponentProps<typeof Parts.NewBelow>, "children"> & {
  labels?: Partial<Pick<ConversationLabels, "newBelow" | "jumpToLatest">>
  children?: ReactNode
}) {
  const labels = { ...conversationLabels, ...labelsProp }
  return (
    <Parts.NewBelow
      className={cnState(
        cn(
          buttonVariants({ variant: "secondary", size: "sm" }),
          "pointer-events-auto rounded-full border border-floating-border shadow-floating transition duration-micro ease-standard starting:translate-y-1 starting:opacity-0 motion-reduce:starting:translate-y-0",
        ),
        className,
      )}
      {...props}
    >
      {({ newBelow }) => (
        <>
          <ArrowDownIcon />
          {children ?? (newBelow > 0 ? labels.newBelow(newBelow) : labels.jumpToLatest)}
        </>
      )}
    </Parts.NewBelow>
  )
}

function ConversationLoadOlder({ className, children, ...props }: ComponentProps<typeof Parts.LoadOlder>) {
  return (
    <Parts.LoadOlder
      className={cnState(cn(buttonVariants({ variant: "ghost", size: "sm" }), "self-center"), className)}
      {...props}
    >
      {children}
    </Parts.LoadOlder>
  )
}

type ConversationProps = Omit<ConversationRootProps, "children"> & {
  /** Names the log, for screen readers and agents. */
  label: string
  labels?: Partial<ConversationLabels>
  /** A `ConversationComposer`, below the log. */
  composer?: ReactNode
  /** Shown in the log while it has no messages. */
  empty?: ReactNode
  /** `ConversationMessage`s, oldest first. */
  children?: ReactNode
}

/**
 * A chat or agent thread: a `role="log"` that follows new messages while the reader is at the end, stops when they
 * scroll up, and offers a "new below" pill that jumps back. A message that grows as it streams keeps the end in view.
 */
function Conversation({ label, labels: labelsProp, composer, empty, children, ...props }: ConversationProps) {
  const labels = { ...conversationLabels, ...labelsProp }
  const hasMessages = Array.isArray(children) ? children.some(Boolean) : Boolean(children)
  return (
    <ConversationRoot {...props}>
      <div className="relative flex min-h-0 flex-1 flex-col">
        <ConversationLog aria-label={label}>
          <ConversationLoadOlder>{labels.loadOlder}</ConversationLoadOlder>
          {hasMessages ? children : empty}
        </ConversationLog>
        <div className="pointer-events-none absolute inset-x-0 bottom-group flex justify-center">
          <ConversationNewBelow labels={labels} />
        </div>
      </div>
      {composer}
    </ConversationRoot>
  )
}

type ConversationMessageLabels = Record<ConversationRole, string>

// Read only by screen readers, as a message's name when it shows no author.
const conversationMessageLabels: ConversationMessageLabels = {
  user: "You",
  assistant: "Assistant",
  agent: "Agent",
  system: "System",
  tool: "Tool",
}

type ConversationMessageProps = Omit<ComponentProps<"article">, "role"> & {
  /** Who sent it; styles it and becomes `data-from`. */
  from: ConversationRole
  /** The sender's name, shown above the message and naming it. */
  author?: ReactNode
  /** An `Avatar` or `AgentAvatar`, beside the message. */
  avatar?: ReactNode
  /** When it was sent, shown as a `RelativeTime`. */
  time?: Instant
  /** Pass one `useNow()` per screen to every message's `now`. */
  now?: Instant
  locale?: string
  /** Still arriving: `aria-busy`, so screen readers wait for the whole message. */
  streaming?: boolean
  /** Buttons under the message, like Copy or Retry. */
  actions?: ReactNode
  /** Identifies it to agents reading the log. */
  messageId?: string
  /** A screen-reader name per role, used when there is no `author`. */
  labels?: Partial<ConversationMessageLabels>
}

const bubbleClassName =
  "group-data-[from=user]/message:rounded-surface group-data-[from=user]/message:bg-primary group-data-[from=user]/message:px-inset-item group-data-[from=user]/message:py-inset-item group-data-[from=user]/message:text-primary-foreground group-data-[from=tool]/message:rounded-control group-data-[from=tool]/message:border group-data-[from=tool]/message:bg-muted group-data-[from=tool]/message:px-inset-item group-data-[from=tool]/message:py-inset-item group-data-[from=tool]/message:font-mono group-data-[from=tool]/message:text-body-sm"

/** One message: an `article` named by its author and time. */
function ConversationMessage({
  from,
  author,
  avatar,
  time,
  now,
  locale,
  streaming,
  actions,
  messageId,
  labels: labelsProp,
  className,
  children,
  ...props
}: ConversationMessageProps) {
  const headerId = useId()
  const labels = { ...conversationMessageLabels, ...labelsProp }
  return (
    <article
      data-slot="conversation-message"
      data-from={from}
      data-message-id={messageId}
      data-streaming={streaming ? "" : undefined}
      aria-labelledby={headerId}
      aria-busy={streaming || undefined}
      className={cn(
        "group/message flex min-w-0 shrink-0 items-start gap-items text-body data-[from=system]:justify-center data-[from=system]:text-caption data-[from=system]:text-muted-foreground data-[from=user]:flex-row-reverse",
        className,
      )}
      {...props}
    >
      {avatar !== undefined && from !== "system" && (
        <div data-slot="conversation-message-avatar" className="flex shrink-0">
          {avatar}
        </div>
      )}
      <div
        data-slot="conversation-message-body"
        className="flex max-w-full min-w-0 flex-col gap-inline group-data-[from=user]/message:items-end group-data-[from=system]/message:items-center group-data-[from=user]/message:max-w-4/5"
      >
        <div
          id={headerId}
          data-slot="conversation-message-header"
          className="flex items-baseline gap-inline text-caption text-muted-foreground"
        >
          {author === undefined ? (
            <span data-slot="conversation-message-author" className="sr-only">
              {labels[from]}
            </span>
          ) : (
            <span data-slot="conversation-message-author" className="font-medium text-foreground">
              {author}
            </span>
          )}
          {time !== undefined && <RelativeTime value={time} now={now} locale={locale} />}
        </div>
        <div data-slot="conversation-message-content" className={cn("min-w-0 break-words", bubbleClassName)}>
          {children}
        </div>
        {actions !== undefined && (
          <div data-slot="conversation-message-actions" className="flex items-center gap-inline">
            {actions}
          </div>
        )}
      </div>
    </article>
  )
}

export {
  Conversation,
  ConversationContext,
  ConversationLoadOlder,
  ConversationLog,
  ConversationMessage,
  ConversationNewBelow,
  ConversationRoot,
  conversationLabels,
  conversationMessageLabels,
  useConversation,
}
export type {
  ConversationApi,
  ConversationLabels,
  ConversationMessageLabels,
  ConversationMessageProps,
  ConversationProps,
  ConversationRole,
  ConversationRootProps,
}

"use client"

import { useState, type FormEvent, type ReactNode } from "react"
import { ArrowUpIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { useConversation } from "@/components/ui/conversation"
import { Textarea, createInputController, type InputController } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

type ConversationComposerLabels = {
  /** Names the text field. */
  message: string
  /** Names the send button. */
  send: string
}

const conversationComposerLabels: ConversationComposerLabels = { message: "Message", send: "Send" }

type ConversationComposerProps = {
  /**
   * Sends the trimmed text. The field empties once it returns, or once a returned Promise resolves; return `false`
   * (or resolve to it) to keep the text, like after a failed send.
   */
  onSend: (text: string) => unknown
  labels?: Partial<ConversationComposerLabels>
  placeholder?: string
  disabled?: boolean
  /** `"enter"` (default): Enter sends and Shift+Enter starts a line. `"mod+enter"`: Cmd/Ctrl+Enter sends. */
  submitShortcut?: "enter" | "mod+enter"
  /** Reads and writes the field from outside, like a suggestion chip that fills it. */
  controller?: InputController
  /** More controls beside Send, like an attach button. */
  actions?: ReactNode
  className?: string
}

/** A message field and a Send button under a `Conversation`: sending jumps the log to the newest message. */
function ConversationComposer({
  onSend,
  labels: labelsProp,
  placeholder,
  disabled,
  submitShortcut = "enter",
  controller,
  actions,
  className,
}: ConversationComposerProps) {
  const labels = { ...conversationComposerLabels, ...labelsProp }
  const [ownController] = useState(createInputController)
  const input = controller ?? ownController
  const [hasText, setHasText] = useState(false)
  const [pending, setPending] = useState(false)
  const conversation = useConversation()

  const send = async () => {
    const text = input.getValue().trim()
    if (!text || disabled || pending) return
    conversation?.jumpToLatest()
    setPending(true)
    const sent = await Promise.resolve(onSend(text)).then(
      (result) => result !== false,
      () => false,
    )
    setPending(false)
    if (sent) input.clear()
  }

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    void send()
  }

  return (
    <form
      data-slot="conversation-composer"
      onSubmit={submit}
      className={cn(
        "flex items-end gap-items border-t border-border bg-background/(--glass-opacity) px-inset-surface py-group",
        className,
      )}
    >
      <Textarea
        controller={input}
        aria-label={labels.message}
        placeholder={placeholder}
        disabled={disabled}
        autoResize
        submitShortcut={submitShortcut}
        rows={1}
        onValueChange={(value: string) => setHasText(value.trim() !== "")}
        className="max-h-40 min-h-control resize-none"
      />
      {actions}
      <Button
        type="submit"
        size="icon"
        aria-label={labels.send}
        loading={pending}
        disabled={disabled || !hasText}
        className="rounded-full"
      >
        <ArrowUpIcon />
      </Button>
    </form>
  )
}

export { ConversationComposer, conversationComposerLabels }
export type { ConversationComposerLabels, ConversationComposerProps }
